#!/usr/bin/env python3
from pwn import *
import os
import struct

def read_binary(filename):
    with open(filename, 'rb') as f:
        return f.read()

def write_binary(filename, data):
    with open(filename, 'wb') as f:
        f.write(data)

def fix_binary(data):
    fixed = bytearray(data)

    # Common patterns where null bytes were replaced
    null_markers = [0x40, 0x38, 0x20, 0x1c, 0x02]

    # Fix architecture
    fixed[0x12:0x14] = b'\x3e\x00'

    # Fix null bytes in ELF header
    # ELF header is 64 bytes
    for i in range(64):
        if fixed[i] in null_markers:
            # Check if this position typically has a null in ELF64 headers
            if i in [7, 8, 0x14, 0x15, 0x16, 0x17, 0x18, 0x19]:
                fixed[i] = 0x00

    # Fix program header table entries
    phoff = 64  # Program header typically starts right after ELF header
    for i in range(phoff, len(fixed)-8):
        if fixed[i] in null_markers:
            # Look for patterns that suggest this should be a null
            if (i % 8 == 0) or (fixed[i-1] > 0x20 and fixed[i-1] < 0x7f):
                fixed[i] = 0x00

    # Fix section names and string table
    for i in range(len(fixed)):
        if fixed[i] in null_markers:
            # If we're in what looks like a string section
            if i > 0 and fixed[i-1] > 0x20 and fixed[i-1] < 0x7f:
                # Check if followed by valid string chars or known patterns
                if i < len(fixed)-1 and (fixed[i+1] > 0x20 and fixed[i+1] < 0x7f):
                    fixed[i] = 0x00

    return bytes(fixed)

def main():
    orig_file = "thoroughlyStripped"
    fixed_file = "thoroughlyStripped_fixed2"

    data = read_binary(orig_file)
    fixed_data = fix_binary(data)
    write_binary(fixed_file, fixed_data)
    os.chmod(fixed_file, 0o755)

    print("Binary has been processed and saved as", fixed_file)

if __name__ == "__main__":
    main()

